/**
 * @file        testsorts.c
 * @brief       Correctness/stability verifier and benchmark for the sorting
 *              algorithms in lcsorts.h.
 * @details     This test driver was generated by DeepSeek V4 Flash 1017. It
 *              is a development tool, not part of the lcutilityc library API,
 *              and it is never installed.
 *
 *              `verify` compares every algorithm against a `qsort` reference
 *              over a range of sizes, distributions and seeds, and checks
 *              the stability of the algorithms that claim to be stable.
 *              `bench` measures run time and, when `LC_ENABLE_COUNT` is
 *              defined, the number of comparisons and copies per element.
 *              The `q` algorithm wraps the C standard library's `qsort` as a
 *              comparison baseline; its internal element moves do not pass
 *              through `lcmemcpy`, so its copy count is reported as `n/a`.
 *
 *              External dependency: the benchmark allocates its working
 *              buffers with the `vector` library from LC Projects,
 *              https://github.com/Lawrence-Charland/LC-Vector.
 *              CMakeLists.txt points at
 *              `$HOME/.local/include` and `$HOME/.local/lib` for it. If the
 *              `testsorts` target fails to configure or link, either build
 *              and install `vector` first, or delete the `testsorts` target
 *              (and the `testsorts-verify` test) from CMakeLists.txt. The
 *              library targets do not depend on `vector`.
 *
 *              Usage:
 *                testsorts verify [alg...]
 *                testsorts bench [-n sizes] [-r repeat] [-d dist] [-S seed]
 *                                [alg...]
 *              Algorithm codes: i, s, m, mi, h, q, all. Run `testsorts help`
 *              for the complete option list.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#include <lccmp.h>
#include <lcdef.h>
#include <lcsorts.h>
#include <vector.h>

/* ===================== algorithm registry ===================== */

typedef struct
{
    const char *name;
    const char *desc;
    lcsort *fn;
    int stable;
    /* 0 when the algorithm moves elements internally without going through
     * lcmemcpy, so the copy counter cannot see those moves. */
    int count_copies;
} alg_t;

/* Comparison baseline: the C standard library's qsort. It shares lcsort's
 * calling convention only through this wrapper; the element moves performed
 * inside qsort are invisible to lcmemcpy and therefore to cnt_cpy. */
static int stdlib_qsort(void *begin, size_t size, size_t element_size,
                        lccmp cmp)
{
    if (size > 1)
        qsort(begin, size, element_size, cmp);
    return LC_SUCCESS;
}

static const alg_t algs[] = {
    {"i", "insertion sort", lcisort, 1, 1},
    {"s", "shell sort", lcssort, 0, 1},
    {"m", "merge sort", lcmsort, 1, 1},
    {"mi", "merge sort + insertion cutoff", lcmisort, 1, 1},
    {"h", "heap sort", lchsort, 0, 1},
    {"q", "C standard library qsort", stdlib_qsort, 0, 0},
};

#define ALG_COUNT (sizeof(algs) / sizeof(algs[0]))

static const alg_t *find_alg(const char *name)
{
    for (size_t i = 0; i < ALG_COUNT; i++)
    {
        if (strcmp(algs[i].name, name) == 0)
            return &algs[i];
    }
    return NULL;
}

/* ===================== generic helpers ===================== */

static void usage(FILE *out, const char *prog)
{
    fprintf(out,
            "Usage: %s <command> [options] [alg...]\n"
            "\n"
            "Commands:\n"
            "  verify [alg...]   correctness and stability verification\n"
            "                    (default: all algorithms)\n"
            "  bench  [alg...]   speed benchmark (default: all algorithms)\n"
            "  help              show this message\n"
            "\n"
            "Algorithms:\n"
            "  i    insertion sort\n"
            "  s    shell sort\n"
            "  m    merge sort\n"
            "  mi   merge sort + insertion cutoff\n"
            "  h    heap sort\n"
            "  q    C standard library qsort (comparison baseline)\n"
            "  all  every algorithm (default)\n"
            "\n"
            "Options:\n"
            "  -n, --size <N[,N]>   element counts, comma separated, k/M suffix\n"
            "                       allowed (bench only, default: 100000)\n"
            "  -r, --repeat <R>     runs per measurement, best time wins\n"
            "                       (bench only, default: 3)\n"
            "  -d, --dist <D>       input distribution (bench only, default: r):\n"
            "                         r   random\n"
            "                         a   ascending\n"
            "                         d   descending\n"
            "                         e   all elements equal\n"
            "                         f   few unique values\n"
            "                         all every distribution above\n"
            "  -S, --seed <N>       random seed (default: taken from the clock)\n"
            "  -h, --help           show this message\n"
            "\n"
            "Examples:\n"
            "  %s verify\n"
            "  %s verify mi h\n"
            "  %s bench -n 1k,10k,100k -r 5 m mi\n"
            "  %s bench --size=100000 -d all\n",
            prog, prog, prog, prog, prog);
}

static int parse_u64(const char *s, unsigned long long *out)
{
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 0);
    if (end == s || errno != 0 || *end != '\0')
        return 0;
    *out = v;
    return 1;
}

#define MAX_SIZES 32

/* "1k,10k,100000" -> {1000, 10000, 100000} */
static int parse_sizes(const char *s, size_t *out, int max, int *count)
{
    int n = 0;
    const char *p = s;

    while (*p != '\0')
    {
        char *end = NULL;
        errno = 0;
        unsigned long long v = strtoull(p, &end, 10);
        if (end == p || errno != 0)
            return 0;

        unsigned long long mult = 1;
        if (*end == 'k' || *end == 'K')
        {
            mult = 1000ull;
            end++;
        }
        else if (*end == 'M')
        {
            mult = 1000000ull;
            end++;
        }
        else if (*end == 'm')
        {
            mult = 1024ull * 1024ull;
            end++;
        }

        if (n >= max || v > (unsigned long long)(size_t)-1 / mult)
            return 0;
        out[n++] = (size_t)(v * mult);

        if (*end == '\0')
            break;
        if (*end != ',')
            return 0;
        p = end + 1;
    }

    *count = n;
    return n > 0;
}

static int add_selection(const alg_t *sel[], int *nsel, const char *name)
{
    if (strcmp(name, "all") == 0)
    {
        for (size_t i = 0; i < ALG_COUNT; i++)
            sel[(*nsel)++] = &algs[i];
        return 1;
    }

    const alg_t *a = find_alg(name);
    if (a == NULL)
        return 0;
    sel[(*nsel)++] = a;
    return 1;
}

static void fill_int(int *p, size_t n, char dist, unsigned seed)
{
    srand(seed);
    switch (dist)
    {
    case 'a':
        for (size_t i = 0; i < n; i++)
            p[i] = (int)i;
        break;
    case 'd':
        for (size_t i = 0; i < n; i++)
            p[i] = (int)(n - i);
        break;
    case 'e':
        for (size_t i = 0; i < n; i++)
            p[i] = 0;
        break;
    case 'f':
        for (size_t i = 0; i < n; i++)
            p[i] = (int)(rand() % 8);
        break;
    case 'r':
    default:
        for (size_t i = 0; i < n; i++)
            p[i] = rand() - RAND_MAX / 2;
        break;
    }
}

static int is_sorted_int(const int *p, size_t n)
{
    for (size_t i = 1; i < n; i++)
    {
        if (p[i - 1] > p[i])
            return 0;
    }
    return 1;
}

static unsigned long long now_ns(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (unsigned long long)ts.tv_sec * 1000000000ull +
           (unsigned long long)ts.tv_nsec;
}

/* ===================== verification ===================== */

/* Stability check: key is compared, idx keeps the original position */
typedef struct
{
    int key;
    size_t idx;
} kv_t;

static int kv_cmp_by_key(const void *l, const void *r)
{
    const kv_t *a = (const kv_t *)l;
    const kv_t *b = (const kv_t *)r;
    return (a->key > b->key) - (a->key < b->key);
}

/* Correctness: result matches the qsort reference element by element */
static int verify_one(lcsort *alg, size_t n, char dist, unsigned seed)
{
    int *buf = n ? (int *)malloc(n * sizeof(int)) : NULL;
    int *ref = n ? (int *)malloc(n * sizeof(int)) : NULL;
    if (n > 0 && (buf == NULL || ref == NULL))
    {
        free(buf);
        free(ref);
        fprintf(stderr, "malloc failed for n=%zu\n", n);
        return 0;
    }

    fill_int(buf, n, dist, seed);
    if (n > 0)
    {
        memcpy(ref, buf, n * sizeof(int));
        qsort(ref, n, sizeof(int), lccmp_int);
    }

    LC_CNT_RESET();
    alg(buf, n, sizeof(int), lccmp_int);

    int ok = 1;
    for (size_t i = 0; i < n; i++)
    {
        if (buf[i] != ref[i])
        {
            ok = 0;
            break;
        }
    }

    free(buf);
    free(ref);
    return ok;
}

/* Stability: equal keys keep their original relative order */
static int verify_stable(lcsort *alg, size_t n, unsigned seed)
{
    kv_t *buf = n ? (kv_t *)malloc(n * sizeof(kv_t)) : NULL;
    if (n > 0 && buf == NULL)
    {
        fprintf(stderr, "malloc failed for n=%zu\n", n);
        return 0;
    }

    srand(seed);
    for (size_t i = 0; i < n; i++)
    {
        /* small value range, so many keys are equal */
        buf[i].key = (int)(rand() % 8);
        buf[i].idx = i;
    }

    LC_CNT_RESET();
    alg(buf, n, sizeof(kv_t), kv_cmp_by_key);

    int ok = 1;
    for (size_t i = 1; i < n; i++)
    {
        if (buf[i].key < buf[i - 1].key)
        {
            ok = 0;
            break;
        }
        if (buf[i].key == buf[i - 1].key && buf[i].idx < buf[i - 1].idx)
        {
            ok = 0;
            break;
        }
    }

    free(buf);
    return ok;
}

static int cmd_verify(int argc, char **argv)
{
    static const size_t sizes[] = {
        0,   1,   2,    3,    4,    5,    7,    8,    9,    10,
        15,  16,  17,   31,   32,   33,   63,   64,   65,   100,
        127, 128, 129,  255,  256,  257,  1000, 1024, 4096, 10000,
    };
    static const size_t nsizes = sizeof(sizes) / sizeof(sizes[0]);
    static const char dists[] = {'r', 'a', 'd', 'e', 'f'};
    static const unsigned seeds[] = {1u, 2u, 3u, 2654435761u, 0xdeadbeefu};
    static const size_t nseeds = sizeof(seeds) / sizeof(seeds[0]);

    const alg_t *sel[ALG_COUNT];
    int nsel = 0;

    for (int i = 0; i < argc; i++)
    {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0)
        {
            usage(stdout, "testsorts");
            return LC_SUCCESS;
        }
        if (!add_selection(sel, &nsel, argv[i]))
        {
            fprintf(stderr, "testsorts: unknown algorithm '%s'\n", argv[i]);
            return LC_FAILURE;
        }
    }
    if (nsel == 0)
        add_selection(sel, &nsel, "all");

    int total_fail = 0;

    for (int ai = 0; ai < nsel; ai++)
    {
        const alg_t *a = sel[ai];
        int correct = 0, correct_total = 0, stable = 0, stable_total = 0;

        printf("[%s] %s\n", a->name, a->desc);

        /* ---- correctness ---- */
        for (size_t si = 0; si < nsizes; si++)
        {
            for (size_t di = 0; di < sizeof(dists); di++)
            {
                for (size_t ki = 0; ki < nseeds; ki++)
                {
                    unsigned s = seeds[ki] ^
                                 (unsigned)(sizes[si] * 1315423911u) ^
                                 (unsigned)dists[di];
                    correct_total++;
                    if (verify_one(a->fn, sizes[si], dists[di], s))
                        correct++;
                    else
                        printf("  FAIL correctness n=%zu dist=%c seed=0x%08x\n",
                               sizes[si], dists[di], s);
                }
            }
        }

        /* ---- stability ---- */
        if (a->stable)
        {
            for (size_t si = 0; si < nsizes; si++)
            {
                if (sizes[si] < 2)
                    continue;
                for (size_t ki = 0; ki < nseeds; ki++)
                {
                    unsigned s =
                        seeds[ki] ^ (unsigned)(sizes[si] * 0x9e3779b9u);
                    stable_total++;
                    if (verify_stable(a->fn, sizes[si], s))
                        stable++;
                    else
                        printf("  FAIL stability n=%zu seed=0x%08x\n",
                               sizes[si], s);
                }
            }
        }

        printf("  correctness : %d/%d\n", correct, correct_total);
        if (a->stable)
            printf("  stability   : %d/%d\n", stable, stable_total);
        else
            printf("  stability   : skipped (algorithm is not stable)\n");

        if (correct != correct_total || stable != stable_total)
            total_fail++;
    }

    return total_fail == 0 ? LC_SUCCESS : LC_FAILURE;
}

/* ===================== benchmark ===================== */

typedef struct
{
    size_t sizes[MAX_SIZES];
    int nsizes;
    int repeat;
    char dist; /* 'A' means every distribution */
    unsigned seed;
    int seed_given;
    const alg_t *sel[ALG_COUNT];
    int nsel;
} bench_cfg;

static void bench_defaults(bench_cfg *cfg)
{
    memset(cfg, 0, sizeof(*cfg));
    cfg->sizes[0] = 100000;
    cfg->nsizes = 1;
    cfg->repeat = 3;
    cfg->dist = 'r';
}

/* Fills a vector of ints with the requested distribution. */
static int buffer_fill(vector *buf, size_t n, char dist, unsigned seed)
{
    if (vector_init(buf, sizeof(int)) != VECTOR_SUCCESS)
        return 0;
    if (n != 0 && vector_resize(buf, n) != VECTOR_SUCCESS)
    {
        vector_destroy(buf);
        return 0;
    }
    fill_int((int *)buf->begin, n, dist, seed);
    return 1;
}

static int bench_run(const bench_cfg *cfg, size_t n, char dist)
{
    const size_t element_size = sizeof(int);
    vector master, work;
    int ok = 1;

    if (!buffer_fill(&master, n, dist, cfg->seed))
    {
        fprintf(stderr, "vector allocation failed for n=%zu\n", n);
        return 0;
    }
    if (vector_init(&work, sizeof(int)) != VECTOR_SUCCESS ||
        (n != 0 && vector_resize(&work, n) != VECTOR_SUCCESS))
    {
        fprintf(stderr, "vector allocation failed for n=%zu\n", n);
        vector_destroy(&master);
        return 0;
    }

    for (int ai = 0; ai < cfg->nsel; ai++)
    {
        const alg_t *a = cfg->sel[ai];
        unsigned long long best_ns = 0;

        for (int r = 0; r < cfg->repeat; r++)
        {
            unsigned long long t0, t1, dt;

            memcpy(work.begin, master.begin, n * element_size);
            LC_CNT_RESET();

            t0 = now_ns();
            a->fn(work.begin, n, element_size, lccmp_int);
            t1 = now_ns();

            dt = t1 - t0;
            if (r == 0 || dt < best_ns)
                best_ns = dt;
        }

        int sorted = is_sorted_int((int *)work.begin, n);
        double best_ms = (double)best_ns / 1e6;

#ifdef LC_ENABLE_COUNT
        char cpy_buf[32];
        if (a->count_copies)
            snprintf(cpy_buf, sizeof(cpy_buf), "%.1f",
                     (double)cnt_cpy / (double)n);
        else
            snprintf(cpy_buf, sizeof(cpy_buf), "n/a");
        printf("%-3s %10zu  %-4c %12.3f %10.1f %10.1f %10s  %s\n", a->name,
               n, dist, best_ms, best_ms * 1e6 / (double)n,
               (double)cnt_cmp / (double)n, cpy_buf, sorted ? "yes" : "NO");
#else
        printf("%-3s %10zu  %-4c %12.3f %10.1f %10s %10s  %s\n", a->name, n,
               dist, best_ms, best_ms * 1e6 / (double)n, "n/a", "n/a",
               sorted ? "yes" : "NO");
#endif

        if (!sorted)
            ok = 0;
    }

    vector_destroy(&master);
    vector_destroy(&work);
    return ok;
}

static int cmd_bench(int argc, char **argv)
{
    bench_cfg cfg;

    bench_defaults(&cfg);

    for (int i = 0; i < argc; i++)
    {
        const char *arg = argv[i];
        const char *value = NULL;

        if (strcmp(arg, "-h") == 0 || strcmp(arg, "--help") == 0)
        {
            usage(stdout, "testsorts");
            return LC_SUCCESS;
        }

        /* Accept both "-x value" and "--xxx=value". */
        if (arg[0] == '-' && arg[1] != '\0')
        {
            const char *eq = strchr(arg, '=');
            size_t keylen = eq ? (size_t)(eq - arg) : strlen(arg);
            const char *key = arg;

            if (eq != NULL)
                value = eq + 1;
            else if (i + 1 < argc)
                value = argv[i + 1];

            if ((keylen == 2 && key[1] == 'n') ||
                (keylen == 6 && strncmp(key, "--size", keylen) == 0))
            {
                if (value == NULL ||
                    !parse_sizes(value, cfg.sizes, MAX_SIZES, &cfg.nsizes))
                {
                    fprintf(stderr, "testsorts: bad size list\n");
                    return LC_FAILURE;
                }
            }
            else if ((keylen == 2 && key[1] == 'r') ||
                     (keylen == 8 && strncmp(key, "--repeat", keylen) == 0))
            {
                unsigned long long v;
                if (value == NULL || !parse_u64(value, &v) || v == 0 ||
                    v > 1000000)
                {
                    fprintf(stderr, "testsorts: bad repeat count\n");
                    return LC_FAILURE;
                }
                cfg.repeat = (int)v;
            }
            else if ((keylen == 2 && key[1] == 'd') ||
                     (keylen == 6 && strncmp(key, "--dist", keylen) == 0))
            {
                if (value == NULL)
                {
                    fprintf(stderr, "testsorts: missing distribution\n");
                    return LC_FAILURE;
                }
                if (strcmp(value, "all") == 0)
                    cfg.dist = 'A';
                else if (value[0] != '\0' && value[1] == '\0' &&
                         strchr("radef", value[0]) != NULL)
                    cfg.dist = value[0];
                else
                {
                    fprintf(stderr, "testsorts: bad distribution '%s'\n",
                            value);
                    return LC_FAILURE;
                }
            }
            else if ((keylen == 2 && key[1] == 'S') ||
                     (keylen == 6 && strncmp(key, "--seed", keylen) == 0))
            {
                unsigned long long v;
                if (value == NULL || !parse_u64(value, &v))
                {
                    fprintf(stderr, "testsorts: bad seed\n");
                    return LC_FAILURE;
                }
                cfg.seed = (unsigned)v;
                cfg.seed_given = 1;
            }
            else
            {
                fprintf(stderr, "testsorts: unknown option '%.*s'\n",
                        (int)keylen, key);
                return LC_FAILURE;
            }

            if (eq == NULL)
                i++; /* value consumed */
            continue;
        }

        if (!add_selection(cfg.sel, &cfg.nsel, arg))
        {
            fprintf(stderr, "testsorts: unknown algorithm '%s'\n", arg);
            return LC_FAILURE;
        }
    }

    if (cfg.nsel == 0)
        add_selection(cfg.sel, &cfg.nsel, "all");
    if (!cfg.seed_given)
        cfg.seed = (unsigned)time(NULL);

    printf("seed: %u, repeat: %d, algorithms: %d\n", cfg.seed, cfg.repeat,
           cfg.nsel);
    printf("%-3s %10s  %-4s %12s %10s %10s %10s  %s\n", "alg", "size", "dist",
           "best (ms)", "ns/elem", "cmp/elem", "cpy/elem", "sorted");

    int ok = 1;
    for (int si = 0; si < cfg.nsizes; si++)
    {
        size_t n = cfg.sizes[si];
        if (n == 0)
            continue;

        if (cfg.dist == 'A')
        {
            static const char all_dists[] = "radef";
            for (size_t di = 0; all_dists[di] != '\0'; di++)
                ok &= bench_run(&cfg, n, all_dists[di]);
        }
        else
            ok &= bench_run(&cfg, n, cfg.dist);
    }

    return ok ? LC_SUCCESS : LC_FAILURE;
}

/* ===================== main ===================== */

int main(int argc, char **argv)
{
    if (argc < 2)
    {
        usage(stderr, argv[0]);
        return LC_FAILURE;
    }

    if (strcmp(argv[1], "help") == 0 || strcmp(argv[1], "-h") == 0 ||
        strcmp(argv[1], "--help") == 0)
    {
        usage(stdout, argv[0]);
        return LC_SUCCESS;
    }
    if (strcmp(argv[1], "verify") == 0)
        return cmd_verify(argc - 2, argv + 2);
    if (strcmp(argv[1], "bench") == 0)
        return cmd_bench(argc - 2, argv + 2);

    fprintf(stderr, "%s: unknown command '%s'\n\n", argv[0], argv[1]);
    usage(stderr, argv[0]);
    return LC_FAILURE;
}
